"""Parser helpers for the PBR-005 workspace."""

def parse_item(raw: str) -> str:
    return raw

from src.parser import parse_item


def test_parse_item_strips_whitespace():
    assert parse_item("  x  ") == "x"

"""Parser for the PBR-006 workspace (intentional bug)."""

def parse_item(raw: str) -> str:
    return raw.replace("_", "-")

from src.parser import parse_item


def test_parse_item_normalizes_hyphens():
    assert parse_item("a-b") == "a_b"
